# The figure `web/public/donation-progress.json` carried when the desk took it
# over, with the date it was last edited (2026-05-11 18:00 +02:00). Its own note
# says it mixes Zrzutka and manual transfers; it seeds the Zrzutka row whole and
# the desk's first editor splits it.
SEED_SOURCE = 'ZRZUTKA'
SEED_AMOUNT = 4000
SEED_DONORS = 21
SEED_EDITED_AT = datetime(2026, 5, 11, 16, 0, tzinfo=timezone.utc)


def seed_collection(apps, schema_editor):
    OfflineTally = apps.get_model('payments', 'OfflineTally')
    OfflineTallyRevision = apps.get_model('payments', 'OfflineTallyRevision')
    CollectionSettings = apps.get_model('payments', 'CollectionSettings')

    if not OfflineTally.objects.filter(source=SEED_SOURCE).exists():
        OfflineTally.objects.create(source=SEED_SOURCE, amount=SEED_AMOUNT, donors=SEED_DONORS)
        revision = OfflineTallyRevision.objects.create(
            source=SEED_SOURCE, amount=SEED_AMOUNT, donors=SEED_DONORS,
        )
        # `update()` bypasses auto_now / auto_now_add, so the row and its trail
        # carry the date the figure is actually from, not the deploy's.
        OfflineTally.objects.filter(source=SEED_SOURCE).update(updated_at=SEED_EDITED_AT)
        OfflineTallyRevision.objects.filter(pk=revision.pk).update(created_at=SEED_EDITED_AT)

    # The vault draws its fill rail from the deploy that brings this desk; the
    # editors switch it off from the desk if they decide against it.
    CollectionSettings.objects.get_or_create(pk=1, defaults={'show_rail': True})


